USE Logicup;
SET NAMES utf8mb4;

-- Trava de segurança: só continua se NÃO houver conteúdo (evita duplicar fases).
SELECT IF((SELECT COUNT(*) FROM modulo) = 0, 'OK: banco vazio, pode seguir',
